import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Web 竞态","description":"","frontmatter":{"title":"Web 竞态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/web-race-condition.md","filePath":"cs/web-race-condition.md","lastUpdated":1789023840000}'),p={name:"cs/web-race-condition.md"};function E(_,a,b,u,m,A){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="web-竞态" tabindex="-1">Web 竞态 <a class="header-anchor" href="#web-竞态" aria-label="Permalink to &quot;Web 竞态&quot;">​</a></h1><div class="epigraph"><p>检查与使用若中间插入另一请求，优惠券、余额、一次性令牌就会被用两次。Web 的并发是多请求，不是只线程库。防御是原子更新与幂等键。</p><footer>—— 据 CWE-362；对照[TOCTOU](/cs/toctou)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/xxe">XXE</a>是解析器。缺口是<strong>时间</strong>：主干 TOCTOU 已给文件竞态；本课落到 HTTP 处理。不给刷余额的操作指导。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先读余额再写，两请求交错。一次性标记非原子。缺口是：数据库约束、行锁、幂等键。</p><h3 id="最终一致" tabindex="-1">最终一致 <a class="header-anchor" href="#最终一致" aria-label="Permalink to &quot;最终一致&quot;">​</a></h3><p>跨服务无事务时要用幂等与对账，不能只靠应用层判断。</p><p><span class="marginnote">CWE-362。禁止利用竞态的步骤。业务逻辑下一课更广。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用原子加减。令牌表唯一约束。下一课业务逻辑漏洞：授权与工作流。</p>',12)),(e(),s(h,null,{default:o(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHK%5B%22%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20GAP%5B%22%E5%8F%A6%E4%B8%80%E8%AF%B7%E6%B1%82%E6%8F%92%E5%85%A5%22%5D%0A%20%20GAP%20--%3E%20USE%5B%22%E4%BD%BF%E7%94%A8%22%5D%0A%20%20ATOM%5B%22%E5%8E%9F%E5%AD%90%E6%9B%B4%E6%96%B0%E6%88%96%E5%94%AF%E4%B8%80%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20OK%5B%22%E4%B8%8D%E8%83%BD%E5%8F%8C%E8%8A%B1%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完整性：不变量在并发下失败。业务逻辑下一课即使单线程也会错。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写并发 PoC。业务逻辑漏洞下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>XXE 是解析；竞态是检查与使用的间隙。</li><li>原子约束优于应用层判断。</li><li>Web 并发等于并行请求。</li><li>下一课业务逻辑。</li><li>出处：CWE-362；<a href="/cs/toctou">toctou</a>。</li></ul>',8))])}const B=i(p,[["render",E]]);export{T as __pageData,B as default};
